<script setup lang="ts">
import {onMounted,ref} from 'vue'; import {useRoute} from 'vue-router'; import {api,describe,newId,projectRole} from '../api'; import type {Draft,DraftItem} from '../types'
const route=useRoute(), project=String(route.params.projectId), id=String(route.params.draftId), root=`/api/projects/${project}/task-drafts/${id}`
const data=ref<Draft|null>(null),error=ref(''),busy=ref(false),canWrite=ref(false), storageKey=`agile-draft-submit:${project}:${id}`, submitKey=ref<string|null>(sessionStorage.getItem(storageKey))
async function load(){try{data.value=await api<Draft>(root);if(data.value.draft.idempotencyKey)submitKey.value=data.value.draft.idempotencyKey}catch(e){error.value=describe(e)}}
async function save(item:DraftItem){busy.value=true;error.value='';try{await api(`${root}/items/${item.id}`,{method:'PATCH',body:JSON.stringify({...item,deadline:item.deadline||null})});await load()}catch(e){error.value=describe(e)}finally{busy.value=false}}
async function remove(item:DraftItem){if(!confirm('确定删除这条草稿项？'))return;busy.value=true;try{await api(`${root}/items/${item.id}`,{method:'DELETE'});await load()}catch(e){error.value=describe(e)}finally{busy.value=false}}
async function confirmDraft(){busy.value=true;error.value='';try{data.value=await api<Draft>(`${root}/confirm`,{method:'POST'})}catch(e){error.value=describe(e)}finally{busy.value=false}}
async function submit(){if(!confirm('提交后将创建正式任务，是否继续？'))return;busy.value=true;error.value='';submitKey.value ||= newId();sessionStorage.setItem(storageKey,submitKey.value);try{data.value=await api<Draft>(`${root}/submit`,{method:'POST',body:JSON.stringify({idempotencyKey:submitKey.value})})}catch(e){error.value=describe(e);await load()}finally{busy.value=false}}
onMounted(async()=>{try {canWrite.value=['OWNER','ADMIN','MEMBER'].includes(await projectRole(project));await load()}catch(e){error.value=describe(e)}})
</script>
<template><div class="page-head"><div><p class="eyebrow">项目 {{project}} / 任务草稿</p><h1>审核任务草稿</h1><p class="muted">检查每个行动项，确认后再提交为正式任务。</p></div><router-link class="button secondary" :to="`/projects/${project}/import`">返回导入</router-link></div><div class="steps"><span>01 导入会议</span><span class="active">02 审核草稿</span><span>03 提交任务</span></div><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="!data && !error" class="muted">正在加载草稿…</p><template v-if="data"><div class="card draft-summary"><div><span class="eyebrow">草稿 #{{id}}</span><h2>来源：{{data.draft.sourceRef || '未知'}}</h2><p class="muted">状态流转：DRAFT → CONFIRMED → SUBMITTING → SUBMITTED；失败可重试，草稿可取消。</p></div><span class="badge status">{{data.draft.status}}</span></div><p v-if="data.draft.failureReason" class="error">{{data.draft.failureReason}}</p><p v-if="!data.items.length" class="card muted">暂无草稿项。</p><form v-for="(item,index) in data.items" :key="item.id" class="card item" @submit.prevent="save(item)"><div class="row"><h2>行动项 {{index+1}}</h2><button v-if="data.draft.status==='DRAFT' && canWrite" type="button" class="danger-link" :disabled="busy" @click="remove(item)">删除</button></div><fieldset :disabled="data.draft.status!=='DRAFT' || busy || !canWrite"><label>任务标题<input v-model.trim="item.title" maxlength="255" required></label><div class="form-grid"><label>负责人<input v-model="item.assigneeName" maxlength="50"></label><label>优先级<select v-model="item.priority"><option value="HIGH">高</option><option value="MEDIUM">中</option><option value="LOW">低</option></select></label><label>截止日期<input v-model="item.deadline" type="date"></label></div><label>描述<textarea v-model="item.description" rows="3"></textarea></label><button class="secondary">保存修改</button></fieldset></form><div class="actions"><button v-if="data.draft.status==='DRAFT' && canWrite" class="primary" :disabled="busy || !data.items.length" @click="confirmDraft">确认草稿</button><button v-if="['CONFIRMED','FAILED'].includes(data.draft.status) && canWrite" class="primary" :disabled="busy" @click="submit">{{data.draft.status==='FAILED'?'使用原提交键重试':'提交正式任务'}}</button><router-link v-if="data.draft.status==='SUBMITTED'" class="button primary" :to="`/projects/${project}/tasks`">查看正式任务 →</router-link></div></template></template>
